{
  "name": "数字输入输出模块",
  "name_en": "Digital I/O Device",
  "manufacturer": "",
  "description": "一种带有多路数字信号线的实验室数字输入/输出设备。各通道通常可配置为输入或输出，并以高/低电平方式工作，用于在实验系统中进行触发、同步、状态检测，以及控制开关、快门、继电器或其他数字逻辑设备。",
  "description_en": "A laboratory digital input/output device with multiple digital lines. Each line can typically be configured as an input or output and operates with high/low logic levels. It is used for triggering, synchronization, state sensing, and control of switches, shutters, relays, or other digital logic hardware in experimental setups.",
  "tag_hints": [
    "digital I/O",
    "TTL trigger",
    "hardware synchronization",
    "digital input",
    "digital output",
    "instrument control",
    "state monitoring"
  ],
  "actions": [
    {
      "action_name": "auto-get_num_lines",
      "description": "获取数字IO线数量",
      "description_en": "Get the number of digital I/O lines."
    },
    {
      "action_name": "auto-set_IO_state",
      "description": "设置单个数字线的输入/输出模式",
      "description_en": "Set the input/output mode of a single digital line."
    },
    {
      "action_name": "auto-get_IO_state",
      "description": "获取单个数字线的输入/输出模式",
      "description_en": "Get the input/output mode of a single digital line."
    },
    {
      "action_name": "auto-set_all_IO_state",
      "description": "设置全部数字线的输入/输出模式",
      "description_en": "Set the input/output mode of all digital lines."
    },
    {
      "action_name": "auto-get_all_IO_state",
      "description": "获取全部数字线的输入/输出模式",
      "description_en": "Get the input/output modes of all digital lines."
    },
    {
      "action_name": "auto-write_line",
      "description": "设置单个输出线的高/低电平",
      "description_en": "Set a single output line high or low."
    },
    {
      "action_name": "auto-write_all_lines",
      "description": "设置全部输出线的高/低电平",
      "description_en": "Set all output lines high or low."
    },
    {
      "action_name": "auto-read_line",
      "description": "读取单个输入线的电平状态",
      "description_en": "Read the logic state of a single input line."
    },
    {
      "action_name": "auto-read_all_lines",
      "description": "读取全部输入线的电平状态",
      "description_en": "Read the logic states of all input lines."
    }
  ]
}

